/**
 * Errors when performing contact actions.
 */
sealed class ContactException: kotlin.Exception() {
    
    class ServerException(
        ) : ContactException() {
        override val message
            get() = ""
    }
    
    class InvalidArgument(
        ) : ContactException() {
        override val message
            get() = ""
    }
    
    class InvalidContact(
        ) : ContactException() {
        override val message
            get() = ""
    }
    
    class ReceivingException(
        ) : ContactException() {
        override val message
            get() = ""
    }
    
    class TransmittingException(
        ) : ContactException() {
        override val message
            get() = ""
    }
    
    class ContactIsOffline(
        ) : ContactException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ContactException> {
        override fun lift(error_buf: RustBuffer.ByValue): ContactException = FfiConverterTypeContactError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeContactError : FfiConverterRustBuffer<ContactException> {
    override fun read(buf: ByteBuffer): ContactException {
        

        return when(buf.getInt()) {
            1 -> ContactException.ServerException()
            2 -> ContactException.InvalidArgument()
            3 -> ContactException.InvalidContact()
            4 -> ContactException.ReceivingException()
            5 -> ContactException.TransmittingException()
            6 -> ContactException.ContactIsOffline()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ContactException): ULong {
        return when(value) {
            is ContactException.ServerException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContactException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContactException.InvalidContact -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContactException.ReceivingException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContactException.TransmittingException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContactException.ContactIsOffline -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: ContactException, buf: ByteBuffer) {
        when(value) {
            is ContactException.ServerException -> {
                buf.putInt(1)
                Unit
            }
            is ContactException.InvalidArgument -> {
                buf.putInt(2)
                Unit
            }
            is ContactException.InvalidContact -> {
                buf.putInt(3)
                Unit
            }
            is ContactException.ReceivingException -> {
                buf.putInt(4)
                Unit
            }
            is ContactException.TransmittingException -> {
                buf.putInt(5)
                Unit
            }
            is ContactException.ContactIsOffline -> {
                buf.putInt(6)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



