            )
            is MessagingException.TransmittingException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is MessagingException.CouldNotGetSessionId -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is MessagingException.MessageNotDelivered -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
