/**
 * MSNP lists.
 */

enum class MsnpList {
    
    /**
     * Your contact list as it appears in the client.
     */
    FORWARD_LIST,
    /**
     * List of people allowed to talk to you and see your presence (only applies if using a [BLP][crate::client::Client::set_blp] of `BL`).
     */
    ALLOW_LIST,
    /**
     * What contacts are blocked.
     */
    BLOCK_LIST,
    REVERSE_LIST,
    PENDING_LIST;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeMsnpList: FfiConverterRustBuffer<MsnpList> {
    override fun read(buf: ByteBuffer) = try {
        MsnpList.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: MsnpList) = 4UL

    override fun write(value: MsnpList, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





